"""TASK-20261002-ee63af review computation (red team): J4 closed forms.

Independent closed-form evaluation of EXP-NISTBIN-451dfa version 4's
definitions (definitions.A, instrument_value, reading_R_B, reading_R_M, rho,
margin, d_star, d_star_of_m, success_criterion.outcome_classes,
routing.rt4_expectation_table, procedure stage 4 (G4), BR-1 clause (b)),
written by this reviewer from the contract text. It imports no producer code
block (CB-1, CB-3, CB-4), not the instrument joint_balance.py, and nothing
under experiments/*/runs/. Input: the JSON written by params.py (primary-input
parameters). Every printed time figure (log2 operation counts, margins) is a
DESIGN FIGURE of the cost model, never a result, and carries the model's
memory figure on the same printed item (Macaulay rows MR_B = D log2 n or
MR_M = W(n, D), relation store log2 k).
"""
import json
import math
import sys
from fractions import Fraction

P = json.load(open(sys.argv[1]))
OMEGAS = (3.0, 2.807, 2.376, 2.0)
M_LO, M_HI, D_LO, D_HI = 2, 30, 2, 64
PAIRS = (("MI-1", "PF-2"), ("MI-1", "PF-1"), ("ceiled", "PF-2"), ("ceiled", "PF-1"))
IN_FORCE = ("MI-1", "PF-2")


def k_of(n, m, kr):
    return Fraction(n, m) if kr == "MI-1" else Fraction(-(-n // m))


def neg_log2_p(n, m, kr, pf):
    k = k_of(n, m, kr)
    lx = float(m * k - n) - math.log2(math.factorial(m))
    if pf == "PF-1":
        return -lx
    return -math.log2(-math.expm1(-(2.0 ** lx)))


def A(n, m, kr="MI-1", pf="PF-2"):
    return float(k_of(n, m, kr)) + neg_log2_p(n, m, kr, pf)


def C_I(n, omega, kr="MI-1", pf="PF-2"):
    best = None
    for m in range(M_LO, min(M_HI, n) + 1):
        v = A(n, m, kr, pf) + 4 * omega * math.log2(n)
        if best is None or v < best[0]:
            best = (v, m)
    return best


_W = {}


def W(n, D):
    key = (n, D)
    if key not in _W:
        _W[key] = math.log2(sum(math.comb(n, d) for d in range(D + 1)))
    return _W[key]


def S(reading, n, D, omega):
    if reading == "R-B":
        return D * omega * math.log2(n)
    return omega * (W(n, D) - W(n, 4) + 4 * math.log2(n))


def rho(r, kc):
    return 0.5 * (math.log2(math.pi) + math.log2(r) - math.log2(4 * kc))


def dstar(a, rh, reading, omega=3.0, n=571):
    for D in range(D_LO, D_HI + 1):
        if a + S(reading, n, D, omega) - rh > 0:
            return D
    return None


def tok(d):
    if d is None:
        return "no crossing at D <= 64"
    if d == D_LO:
        return "D* <= 2"
    return d


def as_int(d):
    return 65 if d is None else d


def classify(vals):
    ints = [as_int(v) for v in vals]
    lo, hi = min(ints), max(ints)
    anynone = any(v is None for v in vals)
    return {"D_star_lo": lo, "D_star_hi": hi, "K1_near": lo <= 11,
            "K2_teens": 12 <= lo and hi <= 20, "K2x_straddle": 12 <= lo <= 20 < hi,
            "K3_far": lo >= 21 and not anynone, "K4_beyond": lo >= 21 and anynone}


def r4(x):
    return round(float(x), 4)


fips = P["fips_rows"]
cert = {c["label"]: c for c in P["certicom_rows"]}
RHO = {lab: rho(int(v["r"]), v["k_c"]) for lab, v in fips.items()}
KOB = {"ECC2K-95": 97, "ECC2K-108": 109, "ECC2K-130": 131, "ECC2K-163": 163,
       "ECC2K-238": 239, "ECC2K-358": 359}
for lab, c in cert.items():
    RHO[lab] = rho(int(c["r"]), KOB.get(lab, 1))
for n in ("155", "185"):
    RHO["Oakley-" + n] = P["oakley"][n]["rho_ub"]
CURVES_AT = {79: ["ECC2-79"], 89: ["ECC2-89"], 97: ["ECC2-97", "ECC2K-95"],
             109: ["ECC2-109", "ECC2K-108"], 131: ["ECC2-131", "ECC2K-130"],
             155: ["Oakley-155"], 163: ["K-163", "B-163", "ECC2-163", "ECC2K-163"],
             185: ["Oakley-185"], 191: ["ECC2-191"], 233: ["K-233", "B-233"],
             239: ["ECC2-238", "ECC2K-238"], 283: ["K-283", "B-283"],
             359: ["ECC2-353", "ECC2K-358"], 409: ["K-409", "B-409"],
             571: ["K-571", "B-571"]}
RT4_TABLE = {79: "++++", 89: "++++", 97: "++++", 109: "++++", 131: "++++",
             155: "++++", 163: "++++", 185: "++++", 191: "++++", 233: "+++-",
             239: "+++-", 283: "++--", 359: "----", 409: "----", 571: "----"}

out = {"script": "j4_closed_forms.py (TASK-20261002-ee63af)", "python": sys.version.split()[0],
       "label": "DESIGN FIGURES of the cost model from the contract's closed forms; never results"}

# ---------------------------------------------------------------- rho column
out["rho_571"] = {lab: {"rho": round(RHO[lab], 7), "carried": c, "diff": RHO[lab] - c}
                  for lab, c in (("K-571", 279.7471), ("B-571", 284.8257))}

# ---------------------------------------------------------------- fixture F1 under the four pairs
fx = []
for kr, pf in PAIRS:
    row = {"k_reading": kr, "P_form": pf}
    ok = True
    for n, tgt, mt in ((571, 186.307, 12), (283, 147.649, 9)):
        v, m = C_I(n, 3.0, kr, pf)
        d = abs(v - tgt)
        p = d <= 5.0e-4 and m == mt
        ok = ok and p
        row["n%d" % n] = {"C_I": round(v, 7), "m_star": m, "slack": 5.0e-4 - d, "passes": p,
                          "MR_B_D4": r4(4 * math.log2(n)), "MR_M_D4": r4(W(n, 4)),
                          "relation_store": r4(k_of(n, m, kr))}
    row["F1"] = "PASS" if ok else "FAIL"
    fx.append(row)
out["fixture_F1_by_pair"] = fx

# ---------------------------------------------------------------- scored cells and classes (reachability)
mstar = C_I(571, 3.0)[1]
out["m_star_in_force"] = mstar
reach = []
for kr, pf in PAIRS:
    a = A(571, mstar, kr, pf)
    vals, cells = [], []
    for c in ("K-571", "B-571"):
        for R in ("R-B", "R-M"):
            d = dstar(a, RHO[c], R)
            vals.append(d)
            cell = {"curve": c, "reading": R, "D_star": tok(d)}
            if d is not None and d > D_LO:
                for tag, dd in (("at_D_star_minus_1", d - 1), ("at_D_star", d)):
                    cell[tag] = {"D": dd, "margin": r4(a + S(R, 571, dd, 3.0) - RHO[c]),
                                 "MR_B": r4(dd * math.log2(571)), "MR_M": r4(W(571, dd)),
                                 "relation_store": r4(k_of(571, mstar, kr))}
            cells.append(cell)
    row = {"k_reading": kr, "P_form": pf, "in_force": (kr, pf) == IN_FORCE, "m": mstar,
           "cells": cells}
    row.update(classify(vals))
    reach.append(row)
out["scored_cells_and_class_flags_by_pair"] = reach

# ---------------------------------------------------------------- sensitivities (directions the producer did not vary)
sens = {}
a = A(571, mstar)
# (s1) K-571 with k_c = 1 (IR-3 admits k = 1 only as an upper bound on rho)
r_k = int(fips["K-571"]["r"])
rk1 = rho(r_k, 1)
v1 = [dstar(a, rk1, R) for R in ("R-B", "R-M")] + [dstar(a, RHO["B-571"], R) for R in ("R-B", "R-M")]
sens["s1_K571_kc_1"] = {"rho_K571_kc1": round(rk1, 4), "cells": [tok(v) for v in v1], **classify(v1)}
# (s2) unscored omegas at m* (context only; enter no class under the contract)
s2 = {}
for om in OMEGAS:
    vv = [dstar(a, RHO[c], R, om) for c in ("K-571", "B-571") for R in ("R-B", "R-M")]
    s2[str(om)] = {"cells": [tok(v) for v in vv], **classify(vv)}
sens["s2_omega_grid_at_m_star_unscored_context"] = s2
# (s3) rho needed for D*_B >= 12 at omega 3 (K2's lower edge) against the largest rho any
#      curve at n = 571 can have (rho_ub with k = 1)
need = a + 11 * 3.0 * math.log2(571)
rub = 0.5 * math.log2(math.pi * (2 ** 571 + 1 + 2 ** (571 / 2 + 1)) / 8)
sens["s3_rho_needed_for_D_B_ge_12"] = {"rho_needed_at_least": r4(need), "rho_ub_571": r4(rub),
                                        "gap_bits": r4(need - rub),
                                        "memory_at_D11": {"MR_B": r4(11 * math.log2(571)), "relation_store": r4(k_of(571, mstar, "MI-1"))}}
# (s4) scored cells read (wrongly) at the ceiled argmin m = 15
m15 = C_I(571, 3.0, "ceiled", "PF-2")[1]
a15 = A(571, m15, "ceiled", "PF-2")
v4 = [dstar(a15, RHO[c], R) for c in ("K-571", "B-571") for R in ("R-B", "R-M")]
sens["s4_ceiled_argmin_cells"] = {"m": m15, "cells": [tok(v) for v in v4], **classify(v4)}
out["sensitivities"] = sens

# ---------------------------------------------------------------- threshold tables (all four pairs)
tabs = {}
for kr, pf in PAIRS:
    t = {}
    for c in ("K-571", "B-571"):
        for R in ("R-B", "R-M"):
            for m in range(M_LO, M_HI + 1):
                t[(c, R, m)] = dstar(A(571, m, kr, pf), RHO[c], R)
    tabs[(kr, pf)] = t
base = tabs[IN_FORCE]
cmp = []
for pair in PAIRS[1:]:
    later = equal = earlier = 0
    mx = 0
    two = 0
    for key, v in base.items():
        d = as_int(tabs[pair][key]) - as_int(v)
        if d > 0:
            later += 1
            mx = max(mx, d)
            two += d >= 2
        elif d == 0:
            equal += 1
        else:
            earlier += 1
    cmp.append({"pair": list(pair), "entries": len(base), "later": later, "equal": equal,
                "earlier": earlier, "max_lateness": mx, "later_by_2_or_more": two})
out["threshold_table_comparisons_vs_in_force"] = cmp
toks = []
for pair, t in tabs.items():
    toks.append({"pair": list(pair), "entries": len(t),
                 "D_le_2_tokens": sum(1 for v in t.values() if v == D_LO),
                 "no_crossing_tokens": sum(1 for v in t.values() if v is None),
                 "grid_edge_m": sorted(set(k[2] for k, v in t.items() if v == D_LO)),
                 "largest_entry": max(as_int(v) for v in t.values()),
                 "entries_ge_12": sum(1 for v in t.values() if as_int(v) >= 12)})
out["threshold_table_tokens"] = toks
out["in_force_table"] = {"%s|%s|%d" % k: tok(v) for k, v in sorted(base.items(), key=lambda kv: (kv[0][0], kv[0][1], kv[0][2]))}
out["tables_by_pair"] = {"%s|%s" % pair: {"%s|%s|%d" % k: tok(v) for k, v in sorted(t.items())} for pair, t in tabs.items()}
out["in_force_table_memory_note"] = "relation store at each m is log2(571/m) under MI-1; MR_B = D log2 571 and MR_M = W(571, D) at the entry D"
out["M8_every_entry_le_m_star_entry"] = all(as_int(base[(c, R, m)]) <= as_int(base[(c, R, mstar)])
                                            for (c, R, m) in base)
neg = [[c, m] for c in ("K-571", "B-571") for m in range(M_LO, M_HI + 1)
       if as_int(base[(c, "R-M", m)]) - as_int(base[(c, "R-B", m)]) < 0]
out["negative_spread_entries"] = neg
out["negative_spread_with_RM_crossing_ge_4"] = sum(1 for c, m in neg if as_int(base[(c, "R-M", m)]) >= 4)

# ---------------------------------------------------------------- RT-4 pre-registered signs vs closed forms
rt4 = []
mismatch = []
for n, curves in sorted(CURVES_AT.items()):
    for j, om in enumerate(OMEGAS):
        ci, m = C_I(n, om)
        for c in curves:
            mg = ci - RHO[c]
            sg = "+" if mg > 0 else "-"
            ok = sg == RT4_TABLE[n][j]
            rt4.append({"n": n, "omega": om, "curve": c, "margin": r4(mg), "sign": sg,
                        "table": RT4_TABLE[n][j], "agrees": ok,
                        "MR_B_D4": r4(4 * math.log2(n)), "MR_M_D4": r4(W(n, 4)),
                        "relation_store": r4(k_of(n, m, "MI-1")), "m_star": m})
            if not ok:
                mismatch.append([n, om, c, r4(mg)])
out["rt4_rows"] = rt4
out["rt4_mismatches"] = mismatch
near = sorted((abs(x["margin"]), x["n"], x["omega"], x["curve"], x["margin"]) for x in rt4 if x["n"] != 571)[:6]
out["rt4_smallest_abs_margins"] = near

# ---------------------------------------------------------------- G4 at omega 3 (MI-1, PF-2) and clause (b)
g4 = {}
for c, n in (("K-283", 283), ("B-283", 283), ("K-163", 163), ("B-163", 163),
             ("K-233", 233), ("B-233", 233), ("ECC2-238", 239), ("ECC2K-238", 239)):
    ci, m = C_I(n, 3.0)
    g4[c] = {"margin": r4(ci - RHO[c]), "MR_B_D4": r4(4 * math.log2(n)),
             "relation_store": r4(k_of(n, m, "MI-1")), "m_star": m}
out["G4_margins_omega3"] = g4
out["G4_passes"] = all(v["margin"] > 0 for v in g4.values())
clause_b = {}
for n, curves in sorted(CURVES_AT.items()):
    ci, m = C_I(n, 3.0)
    clause_b[n] = all(ci - RHO[c] > 0 for c in curves)
out["clause_b_every_curve_positive_omega3"] = clause_b
out["clause_b_degrees"] = [n for n, v in clause_b.items() if v]

# ---------------------------------------------------------------- MI-1 per-cell direction over the claim-(A) grid (PF-2)
lower = equal = higher = 0
eqc = []
minima_lower = 0
for n in sorted(CURVES_AT):
    for m in range(M_LO, min(M_HI, n) + 1):
        cv = A(n, m, "ceiled") + 12 * math.log2(n)
        uv = A(n, m, "MI-1") + 12 * math.log2(n)
        if cv < uv:
            lower += 1
        elif cv == uv:
            equal += 1
            eqc.append([n, m])
        else:
            higher += 1
    if C_I(n, 3.0, "ceiled")[0] < C_I(n, 3.0)[0]:
        minima_lower += 1
out["MI1_cells"] = {"cells": lower + equal + higher, "ceiled_below": lower, "equal": equal,
                    "equal_cells": eqc, "ceiled_above": higher, "minima_ceiled_below": minima_lower}

print(json.dumps(out, indent=1, default=str))

