"""TASK-20261002-ee63af: provenance check of every double-quoted phrase in
the red-team report (outside the hunk table) against the committed bytes of
the sources it cites. Whitespace is normalised; a quote with '...' is split
into segments that must all occur. Reads committed bytes via git show HEAD."""
import re
import subprocess
import sys
import yaml

S = "/tmp/claude-0/-home-user/f42055f8-3588-569d-b7d9-926d696d2468/scratchpad/BATCH-bc5bd5/TASK-20261002-ee63af"
R = "/home/user/crypto-autoresearcher"
SOURCES = [
    "experiments/EXP-NISTBIN-451dfa/specification.yaml",
    "experiments/EXP-NISTBIN-451dfa/specification.v3-frozen-a10a1880.yaml",
    "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/proof-search-map-audit.yaml",
    "coordination/goals/GOAL-ECDLP2M-001/batches/BATCH-bc5bd5/design/TASK-20261002-e11714/revision-worksheet.yaml",
    "coordination/review/nistbin-20261002-bc5bd5/review-plan.yaml",
    "ledger/handoffs/TASK-20261002-ee63af.yaml",
    "ledger/decisions/DEC-20261002-353743.yaml",
    "ledger/decisions/DEC-20260924-124667.yaml",
    "ledger/hypotheses/H-NISTBIN-dec5e1.yaml",
    "inputs/BAILEY-2009-541-ECC2K130/paper_fulltext.md",
]


def norm(t):
    t = t.replace("’", "'").replace("‘", "'").replace("“", '"').replace("”", '"')
    return re.sub(r"\s+", " ", t)


corpus = {}
for p in SOURCES:
    b = subprocess.run(["git", "-C", R, "show", "HEAD:" + p], capture_output=True, check=True).stdout
    corpus[p] = norm(b.decode("utf-8"))

rep = yaml.safe_load(open(S + "/red-team-report.yaml", encoding="utf-8"))["red_team_report"]
rep["J5"].pop("hunk_table", None)


def strings(o, path=""):
    if isinstance(o, dict):
        for k, v in o.items():
            yield from strings(v, path + "/" + str(k))
    elif isinstance(o, list):
        for i, v in enumerate(o):
            yield from strings(v, path + "[%d]" % i)
    elif isinstance(o, str):
        yield path, o


found = notfound = 0
for path, s in strings(rep):
    for q in re.findall(r'"([^"]{6,})"', norm(s)):
        segs = [x.strip(" .,;") for x in re.split(r"\s*\.\.\.\s*", q) if len(x.strip(" .,;")) >= 4]
        hits = []
        for src, txt in corpus.items():
            if segs and all(sg in txt for sg in segs):
                hits.append(src.split("/")[-1])
        ci = []
        if not hits:
            for src, txt in corpus.items():
                if segs and all(sg.lower() in txt.lower() for sg in segs):
                    ci.append(src.split("/")[-1])
        status = "FOUND" if hits else ("FOUND_CASE_INSENSITIVE" if ci else "NOT_FOUND")
        if hits:
            found += 1
        else:
            notfound += 1
        print("%s | %s | %s | %s" % (status, path, q[:110], ",".join(hits or ci)))
print("found", found, "not_found_or_case_only", notfound)

